-- 科研评价与奖励：规则版本、分类适用范围、可解释明细、复核申诉和奖励兑现。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研评价规则" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "规则名称" varchar(200) NOT NULL,
    "版本号" integer NOT NULL DEFAULT 1,
    "适用岗位" varchar(1000),
    "适用学科" varchar(1000),
    "适用研究类型" varchar(1000),
    "评价周期" varchar(30) NOT NULL DEFAULT '年度',
    "生效日期" date,
    "失效日期" date,
    "状态" varchar(10) NOT NULL DEFAULT '草稿',
    "规则说明" varchar(4000),
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价规则" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研评价规则_名称版本" UNIQUE ("规则名称", "版本号"),
    CONSTRAINT "ck_科研评价规则_版本" CHECK ("版本号" > 0),
    CONSTRAINT "ck_科研评价规则_状态" CHECK ("状态" IN ('草稿','生效','停用')),
    CONSTRAINT "ck_科研评价规则_日期" CHECK ("失效日期" IS NULL OR "生效日期" IS NULL OR "失效日期" >= "生效日期")
);

CREATE INDEX IF NOT EXISTS "ix_科研评价规则_适用范围"
    ON "科研评价规则" ("状态", "适用岗位", "适用学科", "适用研究类型");

CREATE TABLE IF NOT EXISTS "科研评价规则项" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "规则编号" bigint NOT NULL,
    "项目代码" varchar(50) NOT NULL,
    "项目名称" varchar(200) NOT NULL,
    "项目分类" varchar(100),
    "计分依据" varchar(2000),
    "权重" numeric(8,3) NOT NULL DEFAULT 1,
    "最高分" numeric(10,2) NOT NULL DEFAULT 100,
    "证据类型" varchar(50),
    "排序" integer NOT NULL DEFAULT 0,
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价规则项" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研评价规则项_代码" UNIQUE ("规则编号", "项目代码"),
    CONSTRAINT "ck_科研评价规则项_权重" CHECK ("权重" > 0),
    CONSTRAINT "ck_科研评价规则项_最高分" CHECK ("最高分" >= 0)
);

CREATE INDEX IF NOT EXISTS "ix_科研评价规则项_规则"
    ON "科研评价规则项" ("规则编号", "是否启用", "排序");

CREATE TABLE IF NOT EXISTS "科研评价结果" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "人员编号" integer NOT NULL,
    "规则编号" bigint NOT NULL,
    "评价年度" integer,
    "周期开始日期" date NOT NULL,
    "周期结束日期" date NOT NULL,
    "适用岗位" varchar(1000),
    "适用学科" varchar(1000),
    "适用研究类型" varchar(1000),
    "总分" numeric(12,2) NOT NULL DEFAULT 0,
    "状态" varchar(10) NOT NULL DEFAULT '待复核',
    "结果摘要" varchar(4000),
    "复核意见" varchar(4000),
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价结果" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研评价结果_周期" UNIQUE ("人员编号", "规则编号", "周期开始日期", "周期结束日期"),
    CONSTRAINT "ck_科研评价结果_日期" CHECK ("周期结束日期" >= "周期开始日期"),
    CONSTRAINT "ck_科研评价结果_状态" CHECK ("状态" IN ('待复核','已发布','申诉中','已修订','作废'))
);

CREATE INDEX IF NOT EXISTS "ix_科研评价结果_人员周期"
    ON "科研评价结果" ("人员编号", "评价年度", "状态");

CREATE TABLE IF NOT EXISTS "科研评价明细" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "评价结果编号" bigint NOT NULL,
    "规则项编号" bigint NOT NULL,
    "证据类型" varchar(50),
    "证据编号" varchar(200),
    "证据标题" varchar(500),
    "原始值" numeric(12,3),
    "权重" numeric(8,3) NOT NULL DEFAULT 1,
    "得分" numeric(12,2) NOT NULL DEFAULT 0,
    "解释" varchar(4000) NOT NULL,
    "核验状态" varchar(10) NOT NULL DEFAULT '待核验',
    "核验人编号" integer,
    "核验时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价明细" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研评价明细_证据" UNIQUE ("评价结果编号", "规则项编号", "证据类型", "证据编号"),
    CONSTRAINT "ck_科研评价明细_得分" CHECK ("得分" >= 0),
    CONSTRAINT "ck_科研评价明细_核验状态" CHECK ("核验状态" IN ('待核验','已核验','不采纳'))
);

CREATE INDEX IF NOT EXISTS "ix_科研评价明细_结果"
    ON "科研评价明细" ("评价结果编号", "规则项编号", "核验状态");

CREATE TABLE IF NOT EXISTS "科研评价申诉" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "评价结果编号" bigint NOT NULL,
    "发起人编号" integer NOT NULL,
    "申诉理由" varchar(4000) NOT NULL,
    "期望处理" varchar(2000),
    "补充证据说明" varchar(4000),
    "状态" varchar(10) NOT NULL DEFAULT '待处理',
    "处理意见" varchar(4000),
    "处理人编号" integer,
    "处理时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价申诉" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研评价申诉_状态" CHECK ("状态" IN ('待处理','处理中','接受','部分接受','驳回','撤回'))
);

CREATE INDEX IF NOT EXISTS "ix_科研评价申诉_结果"
    ON "科研评价申诉" ("评价结果编号", "状态", "建立时间");

CREATE TABLE IF NOT EXISTS "科研评价奖励" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "评价结果编号" bigint NOT NULL,
    "人员编号" integer NOT NULL,
    "奖励名称" varchar(200) NOT NULL,
    "奖励级别" varchar(100),
    "奖励金额" numeric(14,2),
    "状态" varchar(10) NOT NULL DEFAULT '待发放',
    "发放日期" date,
    "备注" varchar(2000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价奖励" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研评价奖励_金额" CHECK ("奖励金额" IS NULL OR "奖励金额" >= 0),
    CONSTRAINT "ck_科研评价奖励_状态" CHECK ("状态" IN ('待发放','已发放','不予发放'))
);

CREATE INDEX IF NOT EXISTS "ix_科研评价奖励_人员"
    ON "科研评价奖励" ("人员编号", "状态", "发放日期");

UPDATE "系统迁移版本"
   SET "版本" = 49,
       "脚本" = '001-049',
       "检查摘要" = '增加科研评价规则版本、可解释结果、申诉和奖励兑现'
 WHERE "编号" = 1;

COMMIT;
